  {"clause_id": "c056", "issues": [
    {"issue": "\"Routine daily prepaid report\" is garbled — \"prepaid\" does not fit a report — and the clause requires a daily report \"Monday through Friday\" while also being \"confirmed daily in writing,\" leaving weekends unaddressed. What is actually owed on non-drilling days is unclear.", "type": 1, "prob": 0.14}
