  {"clause_id": "c057", "issues": [
    {"issue": "\"Non-routine occurrences such as notification of significant shows, intent to core, test or log\" is an open-ended catch-all introduced by \"such as,\" so the enumerated items do not bound the duty. What else counts as non-routine, reportable \"immediately,\" is left to argument.", "type": 1, "prob": 0.21}
