  {"clause_id": "c061", "issues": [
    {"issue": "The introduction requires \"one copy of the following (unless otherwise specified),\" item (a) then requires \"Two final prints,\" and a heading \"THREE COPIES\" precedes items (b)–(e), so the number of copies owed is internally inconsistent. The catch-all \"[a]ny other data pertinent to the drilling, testing and surveying\" has no boundary either.", "type": 1, "prob": 0.22}
  ]},
  {"clause_id": "c062", "issues": [
    {"issue": "\"[F]ull information on the completion progress\" is an open-ended standard that the itemized list \"including one copy of the data listed below\" expressly does not limit. What else \"full information\" requires is undefined.", "type": 1, "prob": 0.16}
