  {"clause_id": "c063", "issues": [
    {"issue": "Exhibit \"C\" directs all reports and data to Farmor's office \"Attn: Mike Stamper,\" while Section 10(B) directs all notices and correspondence to \"ATTN: Lester Zitkus\" at a differently stated address. Which delivery satisfies the notice and well-information obligations is unresolved.", "type": 2, "prob": 0.16}
  ]},
  {"clause_id": "c064", "issues": []},
  {"clause_id": "c065", "issues": [
    {"issue": "The granting language leaves the size of the circle blank and grants the right to \"operate, maintain and rework\" the well, whereas Section 2(D) fixes 80-acre circles for gas wells and 40-acre circles for oil wells and speaks of the right to \"operate, maintain and produce.\" The form and the earning definition do not describe the same estate.", "type": 2, "prob": 0.28}
