  {"clause_id": "c066", "issues": [
    {"issue": "The assignment lasts \"so long as oil and gas ... is produced in paying quantities\" or the well is shut in, with no temporary-cessation savings clause and no definition of paying quantities. Whether a period of non-production terminates the assigned operating rights is left open.", "type": 1, "prob": 0.23}
